import{_ as t,o as r,c as o,a3 as i}from"./chunks/framework.BrO6lPIi.js";const u=JSON.parse('{"title":"命令安全分级系统","description":"本文件系统性地梳理 Agent 端的命令安全分级能力，重点覆盖以下目标：。","frontmatter":{"title":"命令安全分级系统","description":"本文件系统性地梳理 Agent 端的命令安全分级能力，重点覆盖以下目标：。"},"headers":[],"relativePath":"本地代理服务/命令执行引擎/命令安全分级系统/index.md","filePath":"本地代理服务/命令执行引擎/命令安全分级系统/index.md","lastUpdated":null}'),l={name:"本地代理服务/命令执行引擎/命令安全分级系统/index.md"};function a(c,e,n,s,g,h){return r(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="命令安全分级系统" tabindex="-1">命令安全分级系统 <a class="header-anchor" href="#命令安全分级系统" aria-label="Permalink to &quot;命令安全分级系统&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js" target="_blank" rel="noreferrer">agent/src/executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js" target="_blank" rel="noreferrer">agent/src/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/skill/executor.js" target="_blank" rel="noreferrer">agent/src/skill/executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/command-security-check.unit.test.js" target="_blank" rel="noreferrer">agent/test/unit/command-security-check.unit.test.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/path-security.unit.test.js" target="_blank" rel="noreferrer">agent/test/unit/path-security.unit.test.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构与安全边界">项目结构与安全边界</a></li><li><a href="#核心组件总览">核心组件总览</a></li><li><a href="#架构概览">架构概览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与资源控制">性能与资源控制</a></li><li><a href="#安全策略配置指南">安全策略配置指南</a></li><li><a href="#常见威胁与防护措施">常见威胁与防护措施</a></li><li><a href="#故障排查">故障排查</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件系统性地梳理 Agent 端的命令安全分级能力，重点覆盖以下目标：</p><ul><li>命令白名单机制：内置安全命令、动态白名单扩展、自定义命令注册。</li><li>危险命令检测算法：敏感操作识别、路径遍历防护、参数注入检测、命令拼接攻击防护。</li><li>执行权限控制模型：用户角色权限、命令级别授权、沙箱环境隔离、资源访问限制。</li><li>安全策略配置：白名单维护、风险等级定义、审计日志记录、违规处理机制。</li><li>实际安全配置示例与常见威胁防护说明。</li></ul><p>需要特别说明的是，当前仓库中“命令安全”的核心实现集中在 Agent 端，主要包含两类能力：</p><ol><li><strong>文件路径沙箱</strong>：通过 <code>checkPath</code> 控制文件类工具可访问的目录，防止越权读取或写入。</li><li><strong>命令分级管控</strong>：通过 <code>checkCommand</code> 对 shell 命令进行黑名单/灰名单判定，输出 <code>allow</code>、<code>confirm</code>、<code>deny</code> 三级结果。</li></ol><p>此外，Agent 还实现了命令执行器（<code>executor.js</code>），负责子进程创建、流式输出、超时控制、进程终止与环境变量白名单；配置文件（<code>config.js</code>）提供工作目录、允许路径、命令超时等运行时参数；服务端（<code>server.js</code>）将安全检查接入具体 API；技能执行器（<code>skill/executor.js</code>）在技能场景下复用路径与命令安全检查。</p><h2 id="项目结构与安全边界" tabindex="-1">项目结构与安全边界 <a class="header-anchor" href="#项目结构与安全边界" aria-label="Permalink to &quot;项目结构与安全边界&quot;">​</a></h2><p>从安全视角看，Agent 端的安全相关代码分布在以下位置：</p><ul><li><code>agent/src/security.js</code>：路径沙箱与命令分级核心逻辑。</li><li><code>agent/src/executor.js</code>：命令执行器、超时策略、环境变量白名单、进程生命周期管理。</li><li><code>agent/src/config.js</code>：默认配置、工作目录、允许路径、命令超时、内存缓存与写锁。</li><li><code>agent/src/server.js</code>：HTTP/WebSocket 接口入口，调用 <code>checkPath</code> 与 <code>checkCommand</code>。</li><li><code>agent/src/skill/executor.js</code>：技能执行时调用路径检查与命令检查。</li><li><code>agent/test/unit/command-security-check.unit.test.js</code>：命令黑白名单单元测试。</li><li><code>agent/test/unit/path-security.unit.test.js</code>：路径格式规整与硬阻止单元测试。</li></ul><pre class="mermaid">graph TB
Server[&quot;服务端&lt;br/&gt;agent/src/server.js&quot;] --&gt; Security[&quot;安全检查&lt;br/&gt;agent/src/security.js&quot;]
Server --&gt; Executor[&quot;命令执行器&lt;br/&gt;agent/src/executor.js&quot;]
Server --&gt; Config[&quot;配置中心&lt;br/&gt;agent/src/config.js&quot;]
SkillExecutor[&quot;技能执行器&lt;br/&gt;agent/src/skill/executor.js&quot;] --&gt; Security
SkillExecutor --&gt; Executor
Tests[&quot;单元测试&lt;br/&gt;command-security-check / path-security&quot;] --&gt; Security
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L15-L15" target="_blank" rel="noreferrer">agent/src/server.js#L15-L15</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L1-L10" target="_blank" rel="noreferrer">agent/src/config.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/skill/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/skill/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/command-security-check.unit.test.js#L1-L10" target="_blank" rel="noreferrer">agent/test/unit/command-security-check.unit.test.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/path-security.unit.test.js#L1-L10" target="_blank" rel="noreferrer">agent/test/unit/path-security.unit.test.js#L1-L10</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L1-L10" target="_blank" rel="noreferrer">agent/src/config.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L15-L15" target="_blank" rel="noreferrer">agent/src/server.js#L15-L15</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/skill/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/skill/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/command-security-check.unit.test.js#L1-L10" target="_blank" rel="noreferrer">agent/test/unit/command-security-check.unit.test.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/path-security.unit.test.js#L1-L10" target="_blank" rel="noreferrer">agent/test/unit/path-security.unit.test.js#L1-L10</a></li></ul><h2 id="核心组件总览" tabindex="-1">核心组件总览 <a class="header-anchor" href="#核心组件总览" aria-label="Permalink to &quot;核心组件总览&quot;">​</a></h2><p>本节按职责划分，说明命令安全分级系统的核心组件及其交互方式。</p><h3 id="路径沙箱组件" tabindex="-1">路径沙箱组件 <a class="header-anchor" href="#路径沙箱组件" aria-label="Permalink to &quot;路径沙箱组件&quot;">​</a></h3><p>路径沙箱由 <code>security.js</code> 中的 <code>checkPath</code> 实现，主要职责包括：</p><ul><li>路径格式归一化：统一 Windows MSYS 风格、盘符大小写、反斜杠、前导斜杠盘符。</li><li>硬阻止目录：<code>.ai-helper-agent</code> 下的配置文件、配对记录、MCP 配置、日志、回收站、技能状态等不可访问。</li><li>工作目录放行：用户当前工作目录始终可访问，即使未显式加入允许列表。</li><li>允许路径校验：基于 <code>allowedPaths</code> 做前缀匹配，并通过 <code>realpath</code> 解析符号链接后再次校验。</li><li>错误消息国际化：通过 <code>translate</code> 返回可读原因。</li></ul><h3 id="命令分级组件" tabindex="-1">命令分级组件 <a class="header-anchor" href="#命令分级组件" aria-label="Permalink to &quot;命令分级组件&quot;">​</a></h3><p>命令分级由 <code>security.js</code> 中的 <code>checkCommand</code> 实现，主要职责包括：</p><ul><li>黑名单判定：绝对禁止的命令，如格式化磁盘、破坏系统目录、覆盖关键系统文件、fork bomb、恶意管道执行等。</li><li>灰名单判定：需要确认的危险命令，如 <code>sudo</code>、<code>rm -rf</code>、<code>chmod 777</code>、<code>git push -f</code>、全局安装、网络外联、进程终止、系统服务等。</li><li>链式命令拆分：支持 <code>&amp;&amp;</code>、<code>;</code>、<code>|</code>、<code>\\n</code> 等控制符，逐段检测，避免敏感命令藏在非开头位置。</li><li>包装器剥壳：剥离 <code>nohup</code>、<code>time</code>、<code>timeout</code>、<code>env</code>、<code>exec</code>、<code>xargs</code>、<code>sudo</code>、<code>doas</code> 等前缀，暴露真实命令。</li><li>解释器内联载荷：解析 POSIX <code>-c/-e</code>、cmd <code>/c /k</code>、PowerShell <code>-Command/-EncodedCommand</code>。</li><li>命令替换检测：提取 <code>$( … )</code> 与反引号内部子命令，结合只读头命令豁免降低误报。</li><li>路径变形归一化：折叠 <code>//</code>、<code>/.</code>、<code>..</code>，防止通过路径写法绕过系统目录黑名单。</li></ul><h3 id="命令执行器组件" tabindex="-1">命令执行器组件 <a class="header-anchor" href="#命令执行器组件" aria-label="Permalink to &quot;命令执行器组件&quot;">​</a></h3><p>命令执行器由 <code>executor.js</code> 实现，主要职责包括：</p><ul><li>Shell 选择：根据平台与环境变量选择 bash、zsh、fish、cmd、powershell 等。</li><li>子进程创建：使用 <code>child_process.spawn</code>，设置工作目录、安全环境变量、标准输入输出管道。</li><li>流式输出：stdout/stderr 实时广播给 WebSocket 客户端，并限制缓冲区上限。</li><li>超时策略：支持受管模式与非受管模式，有输出才延长，无输出则直接终止。</li><li>进程终止：跨平台递归终止进程组，Windows 使用 <code>taskkill /T /PID</code>，Unix 使用负 PID 信号。</li><li>运行进程缓存：记录 execId、pid、command、startTime、duration，便于调试与监控。</li></ul><h3 id="配置组件" tabindex="-1">配置组件 <a class="header-anchor" href="#配置组件" aria-label="Permalink to &quot;配置组件&quot;">​</a></h3><p>配置组件由 <code>config.js</code> 实现，主要职责包括：</p><ul><li>默认值：端口、主机、工作目录、允许路径、命令超时、文件大小限制、RAG 网络策略、记忆嵌入配置。</li><li>内存缓存：按 mtime 刷新，避免频繁读取磁盘。</li><li>写锁：并发写保护，防止 TOCTOU 问题。</li><li>自动允许：skills 目录与工作目录自动加入允许列表。</li><li>敏感信息落盘混淆：apiKey、token 落盘前加密。</li></ul><h3 id="服务端集成" tabindex="-1">服务端集成 <a class="header-anchor" href="#服务端集成" aria-label="Permalink to &quot;服务端集成&quot;">​</a></h3><p>服务端 <code>server.js</code> 在多个 API 中调用 <code>checkPath</code> 与 <code>checkCommand</code>，例如：</p><ul><li>文件读写 API：先校验路径，再执行操作。</li><li>命令执行 API：先校验命令，再交给 executor 执行。</li><li>技能执行 API：技能脚本中涉及文件与命令时，同样走安全检查。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L231-L760" target="_blank" rel="noreferrer">agent/src/security.js#L231-L760</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L39" target="_blank" rel="noreferrer">agent/src/config.js#L15-L39</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L107-L149" target="_blank" rel="noreferrer">agent/src/config.js#L107-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L799-L799" target="_blank" rel="noreferrer">agent/src/server.js#L799-L799</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1038-L1054" target="_blank" rel="noreferrer">agent/src/server.js#L1038-L1054</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/skill/executor.js#L86-L119" target="_blank" rel="noreferrer">agent/src/skill/executor.js#L86-L119</a></li></ul><h2 id="架构概览" tabindex="-1">架构概览 <a class="header-anchor" href="#架构概览" aria-label="Permalink to &quot;架构概览&quot;">​</a></h2><p>下图展示命令安全分级系统在 Agent 端的整体架构：</p><pre class="mermaid">sequenceDiagram
participant Client as &quot;调用方&quot;
participant Server as &quot;服务端&lt;br/&gt;server.js&quot;
participant Security as &quot;安全检查&lt;br/&gt;security.js&quot;
participant Executor as &quot;命令执行器&lt;br/&gt;executor.js&quot;
participant Config as &quot;配置中心&lt;br/&gt;config.js&quot;
Client-&gt;&gt;Server : &quot;请求执行命令或访问文件&quot;
Server-&gt;&gt;Config : &quot;加载 workdir / allowedPaths / commandTimeout&quot;
Server-&gt;&gt;Security : &quot;checkPath(path)&quot;
Security--&gt;&gt;Server : &quot;{ allowed, reason, resolved }&quot;
alt 路径被拒绝
Server--&gt;&gt;Client : &quot;返回路径拒绝原因&quot;
else 路径允许
Server-&gt;&gt;Security : &quot;checkCommand(command, force)&quot;
Security--&gt;&gt;Server : &quot;{ safe, level, reason }&quot;
alt 命令 deny
Server--&gt;&gt;Client : &quot;返回命令被拒绝&quot;
else 命令 confirm
Server--&gt;&gt;Client : &quot;请求用户确认&quot;
Client--&gt;&gt;Server : &quot;确认或取消&quot;
opt 用户确认
Server-&gt;&gt;Security : &quot;checkCommand(command, true)&quot;
Security--&gt;&gt;Server : &quot;{ safe : true, level : &#39;allow&#39; }&quot;
Server-&gt;&gt;Executor : &quot;executeCommand(command)&quot;
Executor--&gt;&gt;Server : &quot;execId + 流式输出&quot;
Server--&gt;&gt;Client : &quot;转发 stdout/stderr/exit&quot;
end
else 命令 allow
Server-&gt;&gt;Executor : &quot;executeCommand(command)&quot;
Executor--&gt;&gt;Server : &quot;execId + 流式输出&quot;
Server--&gt;&gt;Client : &quot;转发 stdout/stderr/exit&quot;
end
end
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L799-L799" target="_blank" rel="noreferrer">agent/src/server.js#L799-L799</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L107-L149" target="_blank" rel="noreferrer">agent/src/config.js#L107-L149</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="路径沙箱与白名单机制" tabindex="-1">路径沙箱与白名单机制 <a class="header-anchor" href="#路径沙箱与白名单机制" aria-label="Permalink to &quot;路径沙箱与白名单机制&quot;">​</a></h3><p>路径沙箱的核心是 <code>checkPath</code>，其流程如下：</p><pre class="mermaid">flowchart TD
Start([&quot;函数入口&quot;]) --&gt; ValidateInput[&quot;校验输入是否为字符串&quot;]
ValidateInput --&gt; InputValid{&quot;输入有效?&quot;}
InputValid --&gt; |否| ReturnInvalid[&quot;返回路径无效&quot;]
InputValid --&gt; |是| ExpandHome[&quot;展开 ~ 到主目录&quot;]
ExpandHome --&gt; NormalizeFormat[&quot;统一路径格式&quot;]
NormalizeFormat --&gt; ResolvePath[&quot;解析绝对路径&quot;]
ResolvePath --&gt; HardBlocked[&quot;检查硬阻止目录&quot;]
HardBlocked --&gt; IsHardBlocked{&quot;命中硬阻止?&quot;}
IsHardBlocked --&gt; |是| ReturnForbidden[&quot;返回禁止访问代理文件&quot;]
IsHardBlocked --&gt; |否| CheckMemoryDir[&quot;检查记忆存储目录&quot;]
CheckMemoryDir --&gt; MemoryAllowed{&quot;是否记忆目录?&quot;}
MemoryAllowed --&gt; |是| ReturnAllowed[&quot;返回允许&quot;]
MemoryAllowed --&gt; |否| CheckWorkdir[&quot;检查工作目录&quot;]
CheckWorkdir --&gt; WorkdirAllowed{&quot;是否工作目录?&quot;}
WorkdirAllowed --&gt; |是| RealpathCheck[&quot;realpath 硬阻止检查&quot;]
RealpathCheck --&gt; ReturnWorkdirAllowed[&quot;返回允许&quot;]
WorkdirAllowed --&gt; |否| CheckAllowedPaths[&quot;检查 allowedPaths&quot;]
CheckAllowedPaths --&gt; PrefixMatch{&quot;前缀匹配?&quot;}
PrefixMatch --&gt; |否| ReturnNotAllowed[&quot;返回不在允许目录&quot;]
PrefixMatch --&gt; |是| RealpathAgain[&quot;realpath 二次校验&quot;]
RealpathAgain --&gt; FinalCheck[&quot;最终硬阻止与前缀检查&quot;]
FinalCheck --&gt; ReturnFinal[&quot;返回允许或拒绝&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h4 id="关键设计要点" tabindex="-1">关键设计要点 <a class="header-anchor" href="#关键设计要点" aria-label="Permalink to &quot;关键设计要点&quot;">​</a></h4><ul><li><strong>硬阻止目录不可绕过</strong>：<code>.ai-helper-agent</code> 下的配置文件、日志、回收站等绝对禁止访问。</li><li><strong>工作目录永远放行</strong>：即使用户未把 workdir 加入 allowedPaths，也允许访问。</li><li><strong>符号链接防护</strong>：通过 <code>realpath</code> 解析真实路径后再校验，防止通过软链接绕过。</li><li><strong>跨平台兼容</strong>：Windows 盘符大小写不敏感比较，MSYS 路径转换，反斜杠统一为正斜杠。</li><li><strong>允许路径动态扩展</strong>：<code>allowedPaths</code> 来自配置，默认包含工作目录与 skills 目录。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L138-L149" target="_blank" rel="noreferrer">agent/src/config.js#L138-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/path-security.unit.test.js#L10-L106" target="_blank" rel="noreferrer">agent/test/unit/path-security.unit.test.js#L10-L106</a></li></ul><h3 id="命令白名单机制" tabindex="-1">命令白名单机制 <a class="header-anchor" href="#命令白名单机制" aria-label="Permalink to &quot;命令白名单机制&quot;">​</a></h3><p>当前系统中，“白名单”主要体现在两个层面：</p><ol><li><strong>路径白名单</strong>：<code>allowedPaths</code> 配置项决定文件类工具可访问的目录。</li><li><strong>命令白名单</strong>：并非传统意义上的“允许列表”，而是通过黑名单/灰名单反向推导“允许”——未被拦截的命令视为允许。</li></ol><h4 id="内置安全命令" tabindex="-1">内置安全命令 <a class="header-anchor" href="#内置安全命令" aria-label="Permalink to &quot;内置安全命令&quot;">​</a></h4><p>内置安全命令是指那些未被黑名单或灰名单捕获的命令，例如：</p><ul><li><code>ls -la</code></li><li><code>git status</code></li><li><code>npm run build</code></li><li><code>cat README.md</code></li><li><code>ps aux | grep node</code></li></ul><p>这些命令在单元测试中被明确断言为 <code>allow</code>。</p><h4 id="动态白名单扩展" tabindex="-1">动态白名单扩展 <a class="header-anchor" href="#动态白名单扩展" aria-label="Permalink to &quot;动态白名单扩展&quot;">​</a></h4><p>动态白名单扩展主要通过以下方式实现：</p><ul><li><strong>工作目录放行</strong>：workdir 始终允许，无需显式加入 allowedPaths。</li><li><strong>记忆目录放行</strong>：MEMORY_DIR 始终允许，供 Agent 内部管理。</li><li><strong>skills 目录自动加入</strong>：配置加载时自动将 skills 目录加入 allowedPaths。</li></ul><h4 id="自定义命令注册" tabindex="-1">自定义命令注册 <a class="header-anchor" href="#自定义命令注册" aria-label="Permalink to &quot;自定义命令注册&quot;">​</a></h4><p>当前仓库中没有显式的“自定义命令注册表”。但可以通过以下方式间接实现：</p><ul><li><strong>技能系统</strong>：通过 SKILL.md 定义技能，技能执行器会调用 <code>checkPath</code> 与 <code>checkCommand</code>。</li><li><strong>MCP 工具注册</strong>：MCP 协议可扩展工具，但命令执行仍走安全检查。</li><li><strong>配置扩展</strong>：通过 allowedPaths 扩展文件访问范围，但不改变命令分级逻辑。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/command-security-check.unit.test.js#L28-L32" target="_blank" rel="noreferrer">agent/test/unit/command-security-check.unit.test.js#L28-L32</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L142-L162" target="_blank" rel="noreferrer">agent/src/security.js#L142-L162</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L138-L149" target="_blank" rel="noreferrer">agent/src/config.js#L138-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/skill/executor.js#L86-L119" target="_blank" rel="noreferrer">agent/src/skill/executor.js#L86-L119</a></li></ul><h3 id="危险命令检测算法" tabindex="-1">危险命令检测算法 <a class="header-anchor" href="#危险命令检测算法" aria-label="Permalink to &quot;危险命令检测算法&quot;">​</a></h3><p>危险命令检测由 <code>checkCommand</code> 实现，核心算法如下：</p><pre class="mermaid">flowchart TD
Start([&quot;函数入口&quot;]) --&gt; ValidateCommand[&quot;校验命令是否为字符串且非空&quot;]
ValidateCommand --&gt; Valid{&quot;命令有效?&quot;}
Valid --&gt; |否| ReturnDeny[&quot;返回 deny&quot;]
Valid --&gt; |是| CollectScopes[&quot;收集子命令范围&quot;]
CollectScopes --&gt; SubstScopes[&quot;计算命令替换送检集合&quot;]
SubstScopes --&gt; BlacklistCheck[&quot;黑名单逐段检查&quot;]
BlacklistCheck --&gt; Blocked{&quot;命中黑名单?&quot;}
Blocked --&gt; |是| ReturnBlocked[&quot;返回 deny&quot;]
Blocked --&gt; |否| CheckAgentFiles[&quot;检查是否引用代理敏感文件&quot;]
CheckAgentFiles --&gt; Forbidden{&quot;命中硬阻止?&quot;}
Forbidden --&gt; |是| ReturnForbidden[&quot;返回 deny&quot;]
Forbidden --&gt; |否| ForceMode{&quot;force 模式?&quot;}
ForceMode --&gt; |是| ReturnAllow[&quot;返回 allow&quot;]
ForceMode --&gt; |否| GraylistCheck[&quot;灰名单逐段检查&quot;]
GraylistCheck --&gt; GrayHit{&quot;命中灰名单?&quot;}
GrayHit --&gt; |是| ReturnConfirm[&quot;返回 confirm&quot;]
GrayHit --&gt; |否| ReturnSafe[&quot;返回 allow&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><h4 id="敏感操作识别" tabindex="-1">敏感操作识别 <a class="header-anchor" href="#敏感操作识别" aria-label="Permalink to &quot;敏感操作识别&quot;">​</a></h4><p>黑名单与灰名单覆盖了以下敏感操作：</p><ul><li><strong>删除操作</strong>：<code>rm -rf /</code>、<code>rm -rf /usr</code>、<code>rm -rf /etc</code>、<code>rm -rf /var</code> 等。</li><li><strong>提权操作</strong>：<code>sudo</code>、<code>doas</code>、<code>runas</code>。</li><li><strong>权限变更</strong>：<code>chmod 777</code>、<code>chmod 000</code>、<code>chown</code>。</li><li><strong>网络外联</strong>：<code>curl</code>、<code>wget</code>、<code>nc</code>、<code>ssh</code>。</li><li><strong>进程操作</strong>：<code>kill</code>、<code>pkill</code>、<code>killall</code>。</li><li><strong>系统服务</strong>：<code>systemctl</code>、<code>launchctl</code>、<code>crontab</code>、<code>sysctl</code>。</li><li><strong>脚本执行</strong>：外部脚本解释器执行 <code>.sh</code>、<code>.py</code>、<code>.js</code> 等。</li><li><strong>Windows 特定</strong>：<code>rmdir /s</code>、<code>del /f</code>、<code>icacls</code>、<code>reg add/delete/import/load/restore</code>、<code>net user/localgroup</code>、<code>sc stop/delete/config</code>、<code>taskkill /f</code>、PowerShell <code>Remove-Item -Recurse</code>、<code>-EncodedCommand</code>。</li></ul><h4 id="路径遍历防护" tabindex="-1">路径遍历防护 <a class="header-anchor" href="#路径遍历防护" aria-label="Permalink to &quot;路径遍历防护&quot;">​</a></h4><p>路径遍历防护主要通过以下方式实现：</p><ul><li><strong>路径归一化</strong>：折叠 <code>//</code>、<code>/.</code>、<code>..</code>，防止通过路径写法绕过系统目录黑名单。</li><li><strong>realpath 校验</strong>：文件访问时解析真实路径后再校验，防止符号链接绕过。</li><li><strong>硬阻止目录</strong>：<code>.ai-helper-agent</code> 下的关键文件绝对禁止访问。</li></ul><h4 id="参数注入检测" tabindex="-1">参数注入检测 <a class="header-anchor" href="#参数注入检测" aria-label="Permalink to &quot;参数注入检测&quot;">​</a></h4><p>参数注入检测主要通过以下方式实现：</p><ul><li><strong>命令替换提取</strong>：提取 <code>$( … )</code> 与反引号内部子命令，单独送检。</li><li><strong>引号内扫描</strong>：即使拆分器不拆引号内容，也会扫描引号内的替换表达式。</li><li><strong>只读头命令豁免</strong>：<code>echo</code>、<code>printf</code>、<code>cat</code>、<code>head</code>、<code>tail</code>、<code>wc</code>、<code>ls</code>、<code>pwd</code>、<code>date</code>、<code>whoami</code>、<code>hostname</code>、<code>uname</code>、<code>id</code>、<code>env</code>、<code>printenv</code>、<code>which</code>、<code>type</code> 等只读命令的替换直接放行。</li></ul><h4 id="命令拼接攻击防护" tabindex="-1">命令拼接攻击防护 <a class="header-anchor" href="#命令拼接攻击防护" aria-label="Permalink to &quot;命令拼接攻击防护&quot;">​</a></h4><p>命令拼接攻击防护主要通过以下方式实现：</p><ul><li><strong>链式命令拆分</strong>：支持 <code>&amp;&amp;</code>、<code>;</code>、<code>|</code>、<code>\\n</code> 等控制符，逐段检测。</li><li><strong>包装器剥壳</strong>：剥离 <code>nohup</code>、<code>time</code>、<code>timeout</code>、<code>env</code>、<code>exec</code>、<code>xargs</code>、<code>sudo</code>、<code>doas</code> 等前缀。</li><li><strong>解释器内联载荷</strong>：解析 POSIX <code>-c/-e</code>、cmd <code>/c /k</code>、PowerShell <code>-Command/-EncodedCommand</code>。</li><li><strong>深度限制</strong>：嵌套解释器最多递归 3 层，防止死循环。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L384" target="_blank" rel="noreferrer">agent/src/security.js#L285-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L394-L560" target="_blank" rel="noreferrer">agent/src/security.js#L394-L560</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L653-L683" target="_blank" rel="noreferrer">agent/src/security.js#L653-L683</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/command-security-check.unit.test.js#L35-L116" target="_blank" rel="noreferrer">agent/test/unit/command-security-check.unit.test.js#L35-L116</a></li></ul><h3 id="执行权限控制模型" tabindex="-1">执行权限控制模型 <a class="header-anchor" href="#执行权限控制模型" aria-label="Permalink to &quot;执行权限控制模型&quot;">​</a></h3><p>当前系统中的执行权限控制模型主要包括：</p><ul><li><strong>用户角色权限</strong>：未实现细粒度角色权限控制，主要通过 <code>force</code> 参数模拟“用户已确认”。</li><li><strong>命令级别授权</strong>：通过 <code>checkCommand</code> 返回 <code>allow</code>、<code>confirm</code>、<code>deny</code> 三级结果。</li><li><strong>沙箱环境隔离</strong>：通过 <code>checkPath</code> 限制文件访问范围，通过 <code>buildSafeEnv</code> 限制环境变量。</li><li><strong>资源访问限制</strong>：通过 <code>MAX_OUTPUT_BUFFER</code> 限制输出缓冲区大小，通过超时策略限制命令执行时间。</li></ul><h4 id="用户角色权限" tabindex="-1">用户角色权限 <a class="header-anchor" href="#用户角色权限" aria-label="Permalink to &quot;用户角色权限&quot;">​</a></h4><p>当前系统未实现多角色权限模型，但可通过以下方式模拟：</p><ul><li><strong>管理员模式</strong>：通过 <code>force=true</code> 跳过灰名单检查，但仍保留黑名单。</li><li><strong>普通用户模式</strong>：默认行为，所有灰名单命令需用户确认。</li></ul><h4 id="命令级别授权" tabindex="-1">命令级别授权 <a class="header-anchor" href="#命令级别授权" aria-label="Permalink to &quot;命令级别授权&quot;">​</a></h4><p>命令级别授权由 <code>checkCommand</code> 实现：</p><ul><li><strong>allow</strong>：安全命令，直接执行。</li><li><strong>confirm</strong>：危险命令，需用户确认。</li><li><strong>deny</strong>：绝对禁止命令，不可绕过。</li></ul><h4 id="沙箱环境隔离" tabindex="-1">沙箱环境隔离 <a class="header-anchor" href="#沙箱环境隔离" aria-label="Permalink to &quot;沙箱环境隔离&quot;">​</a></h4><p>沙箱环境隔离由 <code>checkPath</code> 与 <code>buildSafeEnv</code> 共同实现：</p><ul><li><strong>文件沙箱</strong>：限制文件访问范围为 workdir 与 allowedPaths。</li><li><strong>环境变量沙箱</strong>：仅允许白名单中的环境变量，防止泄露宿主敏感信息。</li></ul><h4 id="资源访问限制" tabindex="-1">资源访问限制 <a class="header-anchor" href="#资源访问限制" aria-label="Permalink to &quot;资源访问限制&quot;">​</a></h4><p>资源访问限制由 <code>executor.js</code> 实现：</p><ul><li><strong>输出缓冲区限制</strong>：最大 5MB，超过后截断并标记。</li><li><strong>超时策略</strong>：受管模式下，有输出才延长，无输出则直接终止。</li><li><strong>进程树终止</strong>：跨平台递归终止进程组，防止僵尸进程。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L165-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L165-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L298-L323" target="_blank" rel="noreferrer">agent/src/executor.js#L298-L323</a></li></ul><h3 id="安全策略配置" tabindex="-1">安全策略配置 <a class="header-anchor" href="#安全策略配置" aria-label="Permalink to &quot;安全策略配置&quot;">​</a></h3><p>安全策略配置主要由 <code>config.js</code> 提供，关键配置项包括：</p><ul><li><strong>workdir</strong>：工作目录，默认 <code>.ai-helper-agent/workspace</code>。</li><li><strong>allowedPaths</strong>：允许路径列表，默认包含 workdir 与 skills 目录。</li><li><strong>commandTimeout</strong>：命令超时时间，默认 300000ms（5分钟）。</li><li><strong>fileMaxSize</strong>：文件大小限制，默认 50MB。</li><li><strong>ragUrlIngest.allowPrivateNetwork</strong>：RAG URL 导入内网访问策略。</li><li><strong>memoryEmbedding.enabled</strong>：长期记忆语义召回开关。</li></ul><h4 id="白名单维护指南" tabindex="-1">白名单维护指南 <a class="header-anchor" href="#白名单维护指南" aria-label="Permalink to &quot;白名单维护指南&quot;">​</a></h4><ul><li><strong>添加允许路径</strong>：通过 API 更新 <code>allowedPaths</code>，或使用 UI 切换工作目录。</li><li><strong>移除允许路径</strong>：通过 API 从 <code>allowedPaths</code> 中移除。</li><li><strong>注意</strong>：workdir 始终允许，无需显式加入 allowedPaths。</li></ul><h4 id="风险等级定义" tabindex="-1">风险等级定义 <a class="header-anchor" href="#风险等级定义" aria-label="Permalink to &quot;风险等级定义&quot;">​</a></h4><ul><li><strong>低风险</strong>：<code>allow</code>，直接执行。</li><li><strong>中风险</strong>：<code>confirm</code>，需用户确认。</li><li><strong>高风险</strong>：<code>deny</code>，绝对禁止。</li></ul><h4 id="审计日志记录" tabindex="-1">审计日志记录 <a class="header-anchor" href="#审计日志记录" aria-label="Permalink to &quot;审计日志记录&quot;">​</a></h4><p>当前系统未实现完整的审计日志记录，但可通过以下方式间接获取：</p><ul><li><strong>命令执行日志</strong>：executor.js 会记录 execId、command、startTime、duration。</li><li><strong>错误日志</strong>：security.js 与 executor.js 会抛出错误消息。</li><li><strong>WebSocket 输出</strong>：stdout/stderr 实时广播，可用于外部审计。</li></ul><h4 id="违规处理机制" tabindex="-1">违规处理机制 <a class="header-anchor" href="#违规处理机制" aria-label="Permalink to &quot;违规处理机制&quot;">​</a></h4><ul><li><strong>路径违规</strong>：返回 <code>security.pathInvalid</code>、<code>security.forbiddenAgentFile</code>、<code>security.pathNotInAllowedDir</code>、<code>security.cannotResolvePath</code>、<code>security.pathOutOfRange</code>、<code>security.pathCheckError</code>。</li><li><strong>命令违规</strong>：返回 <code>security.commandInvalid</code>、<code>security.commandBlocked</code>。</li><li><strong>用户确认失败</strong>：灰名单命令在未确认时被拒绝。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L39" target="_blank" rel="noreferrer">agent/src/config.js#L15-L39</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L107-L149" target="_blank" rel="noreferrer">agent/src/config.js#L107-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>命令安全分级系统的依赖关系如下：</p><pre class="mermaid">graph TB
Security[&quot;security.js&quot;] --&gt; Config[&quot;config.js&quot;]
Security --&gt; I18n[&quot;i18n.js&quot;]
Executor[&quot;executor.js&quot;] --&gt; Config[&quot;config.js&quot;]
Executor --&gt; I18n[&quot;i18n.js&quot;]
Server[&quot;server.js&quot;] --&gt; Security[&quot;security.js&quot;]
Server --&gt; Executor[&quot;executor.js&quot;]
SkillExecutor[&quot;skill/executor.js&quot;] --&gt; Security[&quot;security.js&quot;]
SkillExecutor --&gt; Executor[&quot;executor.js&quot;]
Tests[&quot;单元测试&quot;] --&gt; Security[&quot;security.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L15-L15" target="_blank" rel="noreferrer">agent/src/server.js#L15-L15</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/skill/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/skill/executor.js#L1-L10</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L15-L15" target="_blank" rel="noreferrer">agent/src/server.js#L15-L15</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/skill/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/skill/executor.js#L1-L10</a></li></ul><h2 id="性能与资源控制" tabindex="-1">性能与资源控制 <a class="header-anchor" href="#性能与资源控制" aria-label="Permalink to &quot;性能与资源控制&quot;">​</a></h2><p>命令安全分级系统在性能与资源控制方面采取了以下措施：</p><ul><li><strong>路径检查优化</strong>：先做前缀匹配，再做 realpath 校验，减少不必要的系统调用。</li><li><strong>命令检查优化</strong>：黑名单优先，快速拒绝高危命令；灰名单仅在必要时触发。</li><li><strong>输出缓冲区限制</strong>：最大 5MB，防止长时间命令占用过多内存。</li><li><strong>超时策略优化</strong>：受管模式下，有输出才延长，无输出则直接终止，避免僵尸进程。</li><li><strong>进程树终止</strong>：跨平台递归终止进程组，确保资源释放。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L164-L178" target="_blank" rel="noreferrer">agent/src/security.js#L164-L178</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L708-L719" target="_blank" rel="noreferrer">agent/src/security.js#L708-L719</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L96-L114" target="_blank" rel="noreferrer">agent/src/executor.js#L96-L114</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L165-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L165-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L500-L549" target="_blank" rel="noreferrer">agent/src/executor.js#L500-L549</a></li></ul><h2 id="常见威胁与防护措施" tabindex="-1">常见威胁与防护措施 <a class="header-anchor" href="#常见威胁与防护措施" aria-label="Permalink to &quot;常见威胁与防护措施&quot;">​</a></h2><p>本节列举常见安全威胁及对应的防护措施。</p><h3 id="威胁-1-路径遍历攻击" tabindex="-1">威胁 1：路径遍历攻击 <a class="header-anchor" href="#威胁-1-路径遍历攻击" aria-label="Permalink to &quot;威胁 1：路径遍历攻击&quot;">​</a></h3><ul><li><strong>威胁描述</strong>：通过 <code>../</code>、<code>//</code>、<code>/.</code> 等路径写法绕过沙箱限制。</li><li><strong>防护措施</strong>： <ul><li>路径归一化：折叠冗余分隔符与相对路径段。</li><li>realpath 校验：解析真实路径后再校验。</li><li>硬阻止目录：<code>.ai-helper-agent</code> 下的关键文件绝对禁止访问。</li></ul></li></ul><h3 id="威胁-2-命令注入攻击" tabindex="-1">威胁 2：命令注入攻击 <a class="header-anchor" href="#威胁-2-命令注入攻击" aria-label="Permalink to &quot;威胁 2：命令注入攻击&quot;">​</a></h3><ul><li><strong>威胁描述</strong>：通过 <code>$( … )</code>、反引号、环境变量等方式注入恶意命令。</li><li><strong>防护措施</strong>： <ul><li>命令替换提取：提取 <code>$( … )</code> 与反引号内部子命令，单独送检。</li><li>引号内扫描：扫描引号内的替换表达式。</li><li>只读头命令豁免：降低误报，避免正常用法被拦截。</li></ul></li></ul><h3 id="威胁-3-命令拼接攻击" tabindex="-1">威胁 3：命令拼接攻击 <a class="header-anchor" href="#威胁-3-命令拼接攻击" aria-label="Permalink to &quot;威胁 3：命令拼接攻击&quot;">​</a></h3><ul><li><strong>威胁描述</strong>：通过 <code>&amp;&amp;</code>、<code>;</code>、<code>|</code> 等控制符拼接敏感命令。</li><li><strong>防护措施</strong>： <ul><li>链式命令拆分：逐段检测，避免敏感命令藏在非开头位置。</li><li>包装器剥壳：剥离 <code>sudo</code>、<code>doas</code> 等前缀，暴露真实命令。</li><li>解释器内联载荷：解析 <code>-c/-e</code>、<code>/c /k</code>、<code>-Command/-EncodedCommand</code>。</li></ul></li></ul><h3 id="威胁-4-提权绕过" tabindex="-1">威胁 4：提权绕过 <a class="header-anchor" href="#威胁-4-提权绕过" aria-label="Permalink to &quot;威胁 4：提权绕过&quot;">​</a></h3><ul><li><strong>威胁描述</strong>：通过 <code>sudo</code>、<code>doas</code>、<code>runas</code> 等提权包装器绕过黑名单。</li><li><strong>防护措施</strong>： <ul><li>包装器剥壳：剥离提权前缀，暴露真实命令。</li><li>黑名单优先级：绝对禁止命令不受 force 影响。</li></ul></li></ul><h3 id="威胁-5-系统文件破坏" tabindex="-1">威胁 5：系统文件破坏 <a class="header-anchor" href="#威胁-5-系统文件破坏" aria-label="Permalink to &quot;威胁 5：系统文件破坏&quot;">​</a></h3><ul><li><strong>威胁描述</strong>：通过 <code>rm -rf /</code>、<code>mkfs</code>、<code>dd of=/dev/</code> 等命令破坏系统文件。</li><li><strong>防护措施</strong>： <ul><li>黑名单覆盖：绝对禁止破坏性命令。</li><li>路径变形归一化：防止通过路径写法绕过。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L457-L479" target="_blank" rel="noreferrer">agent/src/security.js#L457-L479</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L521-L560" target="_blank" rel="noreferrer">agent/src/security.js#L521-L560</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L653-L683" target="_blank" rel="noreferrer">agent/src/security.js#L653-L683</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/command-security-check.unit.test.js#L350-L401" target="_blank" rel="noreferrer">agent/test/unit/command-security-check.unit.test.js#L350-L401</a></li></ul><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><p>本节提供常见故障的排查思路。</p><h3 id="问题-1-路径访问被拒绝" tabindex="-1">问题 1：路径访问被拒绝 <a class="header-anchor" href="#问题-1-路径访问被拒绝" aria-label="Permalink to &quot;问题 1：路径访问被拒绝&quot;">​</a></h3><ul><li><strong>可能原因</strong>： <ul><li>路径不在 allowedPaths 中。</li><li>路径命中硬阻止目录。</li><li>路径包含符号链接，指向被禁止的位置。</li></ul></li><li><strong>排查步骤</strong>： <ol><li>检查 <code>allowedPaths</code> 配置。</li><li>检查路径是否属于 <code>.ai-helper-agent</code> 目录。</li><li>使用 <code>realpath</code> 检查真实路径。</li></ol></li></ul><h3 id="问题-2-命令被拒绝" tabindex="-1">问题 2：命令被拒绝 <a class="header-anchor" href="#问题-2-命令被拒绝" aria-label="Permalink to &quot;问题 2：命令被拒绝&quot;">​</a></h3><ul><li><strong>可能原因</strong>： <ul><li>命令命中黑名单。</li><li>命令命中灰名单且未确认。</li><li>命令引用了代理敏感文件。</li></ul></li><li><strong>排查步骤</strong>： <ol><li>检查命令是否属于黑名单。</li><li>检查是否需要用户确认。</li><li>检查命令是否引用 <code>.ai-helper-agent</code> 目录。</li></ol></li></ul><h3 id="问题-3-命令执行超时" tabindex="-1">问题 3：命令执行超时 <a class="header-anchor" href="#问题-3-命令执行超时" aria-label="Permalink to &quot;问题 3：命令执行超时&quot;">​</a></h3><ul><li><strong>可能原因</strong>： <ul><li>命令长时间无输出。</li><li>超时策略设置为严格模式。</li></ul></li><li><strong>排查步骤</strong>： <ol><li>检查命令是否有输出。</li><li>调整 <code>commandTimeout</code> 配置。</li><li>检查 executor.js 的超时策略。</li></ol></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L165-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L165-L186</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>命令安全分级系统通过路径沙箱与命令分级两大核心机制，构建了较为完整的安全防护体系。其优势在于：</p><ul><li><strong>路径沙箱</strong>：通过硬阻止目录、工作目录放行、允许路径校验、符号链接防护，有效防止文件越权访问。</li><li><strong>命令分级</strong>：通过黑名单/灰名单、链式命令拆分、包装器剥壳、解释器内联载荷解析、命令替换检测，有效识别危险命令。</li><li><strong>执行器安全</strong>：通过环境变量白名单、输出缓冲区限制、超时策略、进程树终止，保障执行环境安全。</li></ul><p>然而，系统仍存在一定局限：</p><ul><li><strong>未实现细粒度角色权限控制</strong>：仅通过 <code>force</code> 参数模拟用户确认。</li><li><strong>未实现完整审计日志</strong>：仅通过错误日志与 WebSocket 输出间接获取。</li><li><strong>未实现自定义命令注册表</strong>：需通过技能系统或 MCP 协议间接扩展。</li></ul><p>未来改进方向包括：</p><ul><li>引入 RBAC 角色权限模型。</li><li>完善审计日志记录与导出功能。</li><li>支持自定义命令注册与动态白名单扩展。</li><li>增强命令语义分析，减少误报与漏报。</li></ul>`,160)])])}const b=t(l,[["render",a]]);export{u as __pageData,b as default};
